const socket = io('http://localhost:5000', {
  query: { token: 'YOUR_JWT_TOKEN' }
});

// 连接成功
socket.on('connected', (data) => {
  console.log('Connected:', data);
});

// 接收消息
socket.on('receive_message', (message) => {
  console.log('New message:', message.content);
  console.log('Message type:', message.message_type);

  // 处理帖子卡片
  if (message.message_type === 'post' && message.post) {
    console.log('Post card:', message.post);
  }

  // 处理评论卡片
  if (message.message_type === 'comment' && message.comment) {
    console.log('Comment card:', message.comment);
  }
});

// 发送文本消息
socket.emit('send_message', {
  token: 'YOUR_JWT_TOKEN',
  receiver_id: 2,
  content: 'Hello!',
  message_type: 'text'
});

// 发送帖子卡片
socket.emit('send_message', {
  token: 'YOUR_JWT_TOKEN',
  receiver_id: 2,
  content: '看看这个帖子',
  message_type: 'post',
  related_id: 123  // 帖子ID
});

// 正在输入
socket.emit('typing', {
  token: 'YOUR_JWT_TOKEN',
  receiver_id: 2,
  is_typing: true
});

// 标记已读
socket.emit('mark_as_read', {
  token: 'YOUR_JWT_TOKEN',
  message_id: 123
});

// 标记通知已读
socket.emit('mark_notification_read', {
  token: 'YOUR_JWT_TOKEN',
  notification_id: 456
});
